// Lane Init: the Blitz lane of Enrich Contacts. One run per launch over the WHOLE company
// list; the lane worries about itself: it walks the list in chunks of 100 companies (the
// size this vendor's API and pacing want), asks the vendor per chunk, and hands each chunk's people
// to the writer helper. The Rootflow only orchestrates. The input item is the Rootflow's contract:
// { base, peopleTableId, companiesTableId, peopleFields, contactSourceMulti, dncDomains,
//   companies:[{recordId, domain, company, band, cap, floor}], parentExecId, clientRecId }.
const inp=$input.first().json||{};
const who='Enrich Contacts Blitz lane';
if(!/^app[A-Za-z0-9]{14}$/.test(String(inp.base||''))) throw new Error(who+' was called without a valid base.');
if(!inp.peopleTableId) throw new Error(who+' was called without peopleTableId.');
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const sd=$getWorkflowStaticData('global');
sd.lane={ execId:String($execution.id), startedAt:new Date().toISOString(), chunks:0, called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', skipped:'', built:0, updated:0, heldUnchanged:0, dupes:0, noKey:0, fenced:0, emailsAppended:0, dnc:0, written:0, updatedWritten:0, writeErrors:0, writeReasons:[], coveredDomains:{}, singleSelectSource:false, companiesIn:companies.length };
const CHUNK=100;
const out=[];
for(let i=0;i<companies.length;i+=CHUNK){ out.push({ json:{ idx:out.length+1, count:Math.ceil(companies.length/CHUNK), companies:companies.slice(i,i+CHUNK) } }); }
if(!out.length) return [{ json:{ _empty:true, idx:0, count:0, companies:[] } }];
return out;

// BZ Companies: the Blitz provider of Enrich Contacts. Blitz keys everything on the company's
// LinkedIn page, so the pass is two calls per company: domain-to-linkedin, then employee-finder.
// One item per company out (the first call's input), or {_none:true}. The floor in Blitz's own
// six job levels (C-Team, VP, Director, Manager, Staff, Other): Staff only at small companies,
// Other always (unknown is not junior). No job_function filter: every function is asked.
const inp=$input.first().json||{};
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const LEVELS={ wide:['C-Team','VP','Director','Manager','Staff','Other'], nonjunior:['C-Team','VP','Director','Manager','Other'], manager:['C-Team','VP','Director','Manager'] };
const out=companies.map(c=>({ json:{ domain:String(c.domain).toLowerCase(), cap:Math.max(1,Math.min(50,Number(c.cap)||20)), jobLevel:LEVELS[c.floor]||LEVELS.wide, body:{ domain:'https://'+String(c.domain).toLowerCase() } } }));
if(!out.length) return [{ json:{ _none:true } }];
return out;

// BZ Roster Requests: the domain-to-linkedin answers (one per company, aligned to BZ Companies by
// index, error items included) -> one employee-finder request per company that resolved. The cap
// is max_results (1 to 50), one page: a cap never exceeds 50, so the second page is never needed.
// Companies that did not resolve, and every error, are carried in _stats for BZ Parse.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const reqs=$('BZ Companies').all().map(i=>i.json||{});
let answers=[]; try{ answers=$('BZ Domain To LinkedIn').all(); }catch(e){}
const st={ resolveCalled:0, resolved:0, unresolved:0, errors:0, noKey:0, firstError:'', failReasons:[] };
const out=[];
answers.forEach((it,i)=>{
  const req=reqs[i]; if(!req||req._none) return;
  st.resolveCalled++;
  const j=it.json||{};
  if(j.error&&j.body===undefined&&j.found===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noKey++; return; }
    st.errors++; const r='Blitz domain-to-linkedin: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  const b=(j.body!==undefined)?j.body:j;
  const status=Number(j.statusCode)||200;
  if(status>=300||!b||typeof b!=='object'){ st.errors++; const r='Blitz domain-to-linkedin HTTP '+status+' '+JSON.stringify(b).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
  const url=String(b.company_linkedin_url||'').trim();
  if(!b.found||!url){ st.unresolved++; return; }
  st.resolved++;
  out.push({ json:{ domain:req.domain, cap:req.cap, companyLinkedin:url, body:{ company_linkedin_url:url, job_level:req.jobLevel, max_results:req.cap, page:1 } } });
});
if(!out.length) return [{ json:{ _none:true, _stats:st } }];
out[0].json._stats=st;
return out;

// BZ Parse: the employee-finder answers (aligned to BZ Roster Requests by index) -> people per
// domain, plus the provider verdict in the shared provider contract (see GL Parse). Employee
// Finder returns no email, no seniority and no department per row: the title comes from the
// person's current experience at this company, seniority and department are derived from the
// title by the caller's merge. Never throws.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[], resolveCalled:0, resolved:0, unresolved:0, noKey:0 };
const people={};
let first={}; try{ first=$('BZ Roster Requests').first().json||{}; }catch(e){}
const rs=first._stats||{};
for(const k of ['resolveCalled','resolved','unresolved','noKey']) st[k]=Number(rs[k])||0;
st.errors+=Number(rs.errors)||0; if(rs.firstError&&!st.firstError) st.firstError=rs.firstError; for(const r of (rs.failReasons||[])) st.failReasons.push(r);
let reqs=[]; try{ reqs=$('BZ Roster Requests').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('BZ Employee Finder').all(); }catch(e){}
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
answers.forEach((it,i)=>{
  const req=reqs[i]; if(!req) return;
  st.called++;
  const j=it.json||{};
  if(j.error&&j.body===undefined&&j.results===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noKey++; return; }
    st.errors++; const r='Blitz employee-finder: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  const b=(j.body!==undefined)?j.body:j;
  const status=Number(j.statusCode)||200;
  if(status>=300||!b||!Array.isArray(b.results)){ st.errors++; const r='Blitz employee-finder HTTP '+status+' '+JSON.stringify(b).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
  const list=people[req.domain]||(people[req.domain]=[]);
  for(const p of b.results){
    st.returned++;
    if(list.length>=req.cap) continue;
    const exps=Array.isArray(p.experiences)?p.experiences:[];
    const here=exps.find(e=>e&&e.job_is_current&&(norm(e.company_domain)===req.domain||String(e.company_linkedin_url||'').replace(/\/+$/,'')===req.companyLinkedin.replace(/\/+$/,'')))||exps.find(e=>e&&e.job_is_current)||exps[0]||{};
    const name=String(p.full_name||((String(p.first_name||'')+' '+String(p.last_name||'')).trim())).trim();
    if(!name) continue;
    list.push({ source:'Blitz', sourceId:String(p.linkedin_id||p.id||''), name:name, title:String(here.job_title||p.headline||'').trim(), seniority:'', department:'', email:'', linkedin:String(p.linkedin_url||'').trim(), phone:'' });
    st.kept++;
  }
});
let status='ok', reason='';
const attempted=st.resolveCalled+st.called;
if(st.noKey&&!st.kept&&!st.errors){ status='skipped'; reason='no credential on the Blitz nodes'; }
else if(attempted&&st.errors>=attempted&&!st.kept){ status='error'; reason=st.firstError; }
else if(!attempted){ status='skipped'; reason='nothing to ask'; }
return [{ json:{ provider:'Blitz', status, reason, stats:st, people } }];

// Writer Input: this chunk's people (from BZ Parse) plus the writer's contract, one item for the
// writer helper. An empty answer still goes through the writer (it costs one held read and returns
// zero), so the lane's counters stay honest and simple.
const ctx=$('Enrich Trigger').first().json||{};
const chunk=$('Chunk Loop').first().json||{};
let parsed={}; try{ parsed=$('BZ Parse').first().json||{}; }catch(e){}
return [{ json:{ base:ctx.base, peopleTableId:ctx.peopleTableId, peopleFields:ctx.peopleFields||[], contactSourceMulti:ctx.contactSourceMulti===true, dncDomains:ctx.dncDomains||[], provider:'Blitz', companies:chunk.companies||[], people:(parsed.people&&typeof parsed.people==='object')?parsed.people:{} } }];

// Lane Tick: adds this chunk's vendor counters (BZ Parse) and writer counters (Call Writer) to the
// lane's running totals in this execution's static data (one execution, so the accumulator holds),
// then emits one unconditional tick so the loop never depends on the payload of the work.
const sd=$getWorkflowStaticData('global'); const a=sd.lane;
const n=(v)=>Number(v)||0;
let p={}; try{ p=$('BZ Parse').first().json||{}; }catch(e){}
const s=p.stats||{};
a.chunks++; a.called+=n(s.called); a.returned+=n(s.returned); a.kept+=n(s.kept); a.credits+=n(s.credits); a.errors+=n(s.errors);
if(!a.firstError&&s.firstError) a.firstError=String(s.firstError).slice(0,200);
if(p.status==='skipped'&&p.reason&&p.reason!=='nothing to ask') a.skipped=String(p.reason);
if(p.status==='error'&&!a.firstError) a.firstError=String(p.reason||'').slice(0,200);
let w={}; try{ w=$('Call Writer').first().json||{}; }catch(e){}
if(w.error&&w.written===undefined){ a.writeErrors+=1; if(a.writeReasons.length<5) a.writeReasons.push('writer crashed: '+String((w.error&&w.error.message)||w.error).slice(0,160)); }
else { for(const k of ['built','updated','heldUnchanged','dupes','noKey','fenced','emailsAppended','dnc','written','updatedWritten','writeErrors']) a[k]+=n(w[k]); if(w.singleSelectSource) a.singleSelectSource=true; for(const r of (w.writeReasons||[])){ if(a.writeReasons.length<5&&a.writeReasons.indexOf(r)<0) a.writeReasons.push(r); } for(const d of (w.coveredDomains||[])) a.coveredDomains[d]=1; }
return [{ json:{ tick:true, chunk:a.chunks } }];

// Lane Log: the lane's own Hub row, keyed "<parent execution>-blitz", Automation
// "Enrich Contacts Blitz", Client attached. Status computed: a skipped lane (no credential,
// out of credits, nothing to ask) is Succeeded with a Skipped line; vendor errors and refused
// writes count as errors; Failed only when every call failed and nothing was written.
const ctx=$('Enrich Trigger').first().json||{};
const a=$getWorkflowStaticData('global').lane||{};
const n=(v)=>Number(v)||0;
const covered=Object.keys(a.coveredDomains||{}).length;
const failed=n(a.errors)+n(a.writeErrors);
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(a.startedAt).getTime())/1000)); }catch(e){}
const allFailed=n(a.called)>0&&n(a.errors)>=n(a.called)&&!n(a.written);
const lines=[
  '**Blitz: '+n(a.companiesIn)+' companies asked in '+n(a.chunks)+' chunk'+(n(a.chunks)===1?'':'s')+', '+n(a.returned)+' people returned, '+n(a.built)+' new, '+n(a.updated)+' held filled, '+n(a.written)+' rows written**',
  '', '**Parent run:** '+(ctx.parentExecId||'?')+' (this row is the Blitz lane of it)',
  '', '- **Vendor:** called '+n(a.called)+', returned '+n(a.returned)+', kept '+n(a.kept)+(n(a.credits)?', credits '+(Math.round(n(a.credits)*100)/100):'')+(n(a.errors)?', errors '+n(a.errors)+(a.firstError?' ('+a.firstError+')':''):''),
  '- **Merge:** '+n(a.built)+' new rows; '+n(a.updated)+' held rows filled ('+n(a.emailsAppended)+' emails appended); '+n(a.heldUnchanged)+' held unchanged; '+n(a.dupes)+' same-person merges; '+n(a.noKey)+' without a usable first name; '+n(a.fenced)+' LinkedIn URLs rejected by the name fence; '+n(a.dnc)+' on the DNC list',
  '- **Written (confirmed by Airtable):** '+n(a.written)+' ('+n(a.updatedWritten)+' updates of held rows)'+(n(a.writeErrors)?', '+n(a.writeErrors)+' refused':''),
  '- **Companies with at least one person after this lane:** '+covered
];
if(a.singleSelectSource) lines.push('- **Contact Source is a single select on this base:** only the first source per person was recorded');
if(a.skipped) lines.push('', '**Skipped ('+a.skipped+')**');
if((a.writeReasons||[]).length){ lines.push('', '**Write failures**'); for(const r of a.writeReasons) lines.push('- '+r); }
const log={ 'Execution ID':(ctx.parentExecId||String($execution.id))+'-blitz', 'Automation':'Enrich Contacts Blitz', 'Status':allFailed?'Failed':(failed?'Succeeded with errors':'Succeeded'), 'Trigger':'event', 'Errors':failed, 'Run at':a.startedAt, 'Target':'People ('+(ctx.peopleTableId||'')+')', 'Records In':n(a.companiesIn), 'Records Out':n(a.written), 'Duration s':dur, 'Description':lines.join('\n'), 'Tally':JSON.stringify(Object.assign({}, a, { coveredDomains:covered })), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id };
if(ctx.clientRecId) log['Client']=[ctx.clientRecId];
return [{ json:log }];

// Lane Response: the last node, what the Rootflow receives from this lane: counters only.
const a=$getWorkflowStaticData('global').lane||{};
const covered=Object.keys(a.coveredDomains||{});
return [{ json:{ provider:'Blitz', status:a.skipped?'skipped':((a.called&&a.errors>=a.called&&!a.written)?'error':'ok'), reason:a.skipped||a.firstError||'', chunks:a.chunks, called:a.called, returned:a.returned, kept:a.kept, credits:a.credits, errors:a.errors, built:a.built, updated:a.updated, dupes:a.dupes, fenced:a.fenced, emailsAppended:a.emailsAppended, dnc:a.dnc, written:a.written, writeErrors:a.writeErrors, singleSelectSource:!!a.singleSelectSource, coveredDomains:covered } }];
